"""Finalize the 18-state pilot only when every state passed and is sealed."""
from pathlib import Path
import json,statistics,subprocess,sys
out=Path(__file__).resolve().parent
subprocess.run([sys.executable,'-B','-X','utf8',str(out/'verify_pilot_results.py')],check=True)
def read(p):return json.loads(Path(p).read_text())
def write(p,v):Path(p).write_text(json.dumps(v,indent=2,ensure_ascii=False,allow_nan=False)+'\n',encoding='utf-8')
checks=read(out/'verification.json'); assert checks['status']=='passed_all_18'
summary=read(out/'summary.json');assert summary['completed']==18
exports=[read(out/('export_'+g+'_process.json')) for g in ('nominal','sphere','ellipsoid')]
solves=[read(out/('solve_'+g+'_tepc_'+str(k)+'_process.json')) for g in ('nominal','sphere','ellipsoid') for k in range(2,8)]
assert all(v['status']=='completed' for v in exports+solves)
e=statistics.median(v['elapsed_s'] for v in exports);s=statistics.median(v['elapsed_s'] for v in solves)
res={'status':'all_18_completed_numerical_checks_passed','matlab_exports':3,'fresh_material_blocks':12,
     'linear_factorizations':18,'RHS':36,'threads':4,'parpool':False,
     'peak_sampled_process_tree_rss_gib':max(v['peak_rss_gib'] for v in exports+solves),
     'memory_guard_gib':32,'memory_sampling_interval_s':2,
     'export_elapsed_s':[v['elapsed_s'] for v in exports],'solve_elapsed_s':[v['elapsed_s'] for v in solves],
     'median_export_s':e,'median_state_process_s':s,
     'sum_stage_process_elapsed_s':sum(v['elapsed_s'] for v in exports+solves),
     'output_size_gib':sum(p.stat().st_size for p in out.rglob('*') if p.is_file())/2**30,
     'projected_same_mesh_minutes':{'four_volume_probes_one_sphere_one_montage':4*(e+s)/60,
       '16_probes_four_parameters_one_geometry_one_montage':16*(e+s)/60,
       '48_maps_three_geometries_all_six_montages_288_solves':(48*e+288*s)/60},
     'projection_limits':'Measured same-mesh costs; excludes new-map preparation, retries and refined-mesh cost; no new perturbation solves launched',
     'spatial_convergence':False,'physical_validation':False,'4D_registration':False}
write(out/'resource_and_next_stage_report.json',res)
lines=['# Электрический пилот трёх статических форм сердца','',
 'Выполнены все 18 состояний: три геометрии × TEPC-2…TEPC-7. Это новые решения с заново собранными материальными блоками EIDORS. Старые тканевые блоки и старые поля не использованы для расчёта изменённой формы.','',
 '## Постановка','',
 'Одна замороженная сетка Nix, 791 141 узел, 4 448 426 тетраэдров; целое сердце — однородная эффективная смесь крови и миокарда. Частота 50 кГц задаёт выбранные вещественные проводимости; ёмкостная часть не моделируется. Контакты — 5 мм. Один и тот же набор удельных сопротивлений использован во всех состояниях: мягкие ткани 12,97545; лёгкие 6,77928; сердце 3,27186; кости 48,44513 Ом·м. Это середина прежней расчётной сетки по ρ, а не измеренные индивидуальные свойства.','',
 'Сфера сохраняет аналитический объём и объёмный центр. Эллипсоид построен по моментам с приведением к тому же аналитическому объёму. Каждый вариант накладывается на неизменный фон: исходное сердце заменено мягкими тканями, фоновые лёгкие и кости сохранены; сердце имеет приоритет внутри своей новой области. Это замена материалов, а не механическая модель.','',
 'Автоматическая маска целевой фазы и преобразованная индивидуальная опорная форма остаются отдельными анатомическими представлениями. В этом статическом пилоте их межфазное сравнение и совмещение с 4D не выполнялись.','',
 '## Полученный отклик','',
 'Различия отсчитываются от исходного сердца на этой же сетке, а не от экспериментального эталона. ΔZ сохраняет знак; относительная разность нормирована на |Z исходного сердца|.','',
 '| Сборка | Исходное сердце, Ом | Сфера, Ом | ΔZ сферы, % | Эллипсоид, Ом | ΔZ эллипсоида, % |','|---|---:|---:|---:|---:|---:|']
lookup={(r['geometry'],r['montage']):r for r in summary['rows']}
for k in range(2,8):
 m='tepc_'+str(k);a=lookup['nominal',m];b=lookup['sphere',m];c=lookup['ellipsoid',m]
 lines.append(f"| TEPC-{k} | {a['Z_ohm']:.6f} | {b['Z_ohm']:.6f} | {b['delta_Z_vs_nominal_percent']:+.3f} | {c['Z_ohm']:.6f} | {c['delta_Z_vs_nominal_percent']:+.3f} |")
lines+=['','Таблица показывает зависимость базового электрического отклика от способа замещения. Она не устанавливает точность производных по координатам/объёму, устойчивость на других состояниях ρ или пригодность формы для восстановления УО/ФВ. Меньшая ошибка базового Z сама по себе не определяет лучшую динамическую модель.','',
 '## Численные проверки','',
 f"Максимальная относительная невязка: {checks['max_relative_residual']:.3g}; максимальное расхождение по взаимности: {checks['max_reciprocity_absolute_ohm']:.3g} Ом; ошибка восстановленного тока: {checks['max_current_error_A']:.3g} А. Проверена также исключённая при фиксации потенциала строка заземления. Новые неоднородные матрицы сопоставлены с calc_system_mat EIDORS для фактических проводимостей. Шесть nominal воспроизводят прежний пилот с максимальным расхождением {checks['nominal_regression_max_abs_ohm']:.3g} Ом. Это внутренние численные проверки, не независимая физическая валидация.",'',
 '## Ограничение пространственного разрешения','',
 'В сердечной области медианное ребро тетраэдра составляет около 15,8–15,9 мм; исходное сердце представлено 1963 тетраэдрами. Общее число элементов и размер вокселя КТ не задают разрешение сердечной границы в этой сетке. Модель классифицирует тетраэдр целиком по его центру; дробные пересечения не интегрируются.','',
 'Дешёвый аудит карт показал: для сферы центральный фактический шаг объёма при заданном ±1% отличается от аналитического на −24,66%, для эллипсоида — на +27,02%. При ±2% различия равны −11,69% и +16,28%. Перенос без изменения аналитического объёма также меняет дискретный объём материала. Поэтому численно малые невязки решателя не делают текущую постановку готовой к количественным производным по геометрии.','',
 '## Ресурсы и минимальное продолжение','',
 f"Медиана новой сборки EIDORS: {e:.1f} с. Медиана отдельного процесса решения: {s:.1f} с. Максимальный наблюдавшийся RSS дерева процесса: {res['peak_sampled_process_tree_rss_gib']:.2f} ГиБ (выборка раз в 2 с). Все факторизации прошли предварительную символическую оценку памяти; лимит 32 ГиБ не достигнут. Контактные матрицы различных TEPC различаются, поэтому между ними факторизация не переиспользуется. В одной сборке прямой и взаимный RHS используют одну факторизацию.",'',
 'Рекомендуемый ближайший шаг — оценить локальное уточнение сетки в объединённой области всех рассматриваемых сердечных форм и планируемых перемещений. Сначала повторить на уточнённой геометрии аудит объёмов/границ без FEM. Альтернативу с интегрированием долей материалов внутри тетраэдров рассматривать отдельно: она уменьшает ступенчатость меток, но сама по себе не доказывает точность поля на грубой сетке.','',
 f"Самый дешёвый прямой электрический тест h/h2 — четыре объёмные пробы одной сферы в одной сборке (−δV, +δV, −δV/2, +δV/2) с уже имеющимся центральным состоянием. На неизменной нынешней сетке это около {4*(e+s)/60:.1f} мин; после локального уточнения время требуется измерить заново. Первой можно оставить TEPC-2 ради непрерывности технического контроля, без утверждения её оптимальности. На текущих ступенчатых картах такой тест будет диагностикой погрешности, а не готовой оценкой физиологической чувствительности.",'',
 f"Расширение до трёх переносов и объёма потребует 16 новых состояний на одну форму и сборку, ориентировочно {16*(e+s)/60:.1f} мин на текущей сетке. Полный вариант 3 формы × 16 возмущений × 6 сборок требует 48 новых карт/экспортов и 288 решений, около {(48*e+288*s)/60:.1f} мин без подготовки геометрии. Эти дополнительные FEM не запущены. Шаги должны оставаться численными пробами; физиологические амплитуды ими не задаются.",'',
 '## Воспроизводимость и передача','',
 'Команды и политика возобновления — handoff.md. Манифест входов — plan.json; сводки — summary.json/summary.csv; проверки — verification.json и nominal_regression.json; ресурсы — resource_and_next_stage_report.json; аудит карт — perturbation_map_audit.json. Полные прямые и взаимные поля сохранены по каждому состоянию. Реализации в src/ и tools/ созданы отдельно; существующие helper, README, реестр и ноутбуки не изменялись; коммит не выполнялся.']
(out/'RESULTS_AND_HANDOFF.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print(json.dumps(res,indent=2))
